/* global URL, console, process */

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import openapiTS, { astToString } from "openapi-typescript";

const root = new URL("../", import.meta.url);
const source = JSON.parse(readFileSync(new URL("../docs/openapi.json", root), "utf8"));
const generated = [
  "/**",
  " * This file was auto-generated by openapi-typescript.",
  " * Do not make direct changes to the file.",
  " */",
  "",
].join("\n") + "\n" + astToString(await openapiTS(source));
const expected = readFileSync(new URL("src/api/schema.d.ts", root), "utf8");
const temp = mkdtempSync(join(tmpdir(), "qscan-contract-"));
try {
  const actualPath = join(temp, "schema.d.ts");
  writeFileSync(actualPath, generated);
  if (generated !== expected) {
    console.error("TypeScript API contract is stale; run npm run generate:api");
    process.exitCode = 1;
  } else {
    console.log("TypeScript API contract is up to date");
  }
} finally {
  rmSync(temp, { recursive: true, force: true });
}
